import pandas as pd

def clean(df):
    df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235)]
    return df

def answer(df):
    grouped = df.groupby('species')['flipper_length_mm'].mean().reset_index()
    result = {row['species']: row['flipper_length_mm'] for _, row in grouped.iterrows()}
    return result
